-                            keyCurrentlyInUse.set(new SingleUseKey(newKey.v1(), newKey.v2(), MIN_NONCE));
-                        }
-                    }
-                }
-            }
-            throw new IllegalStateException("Failure to generate new key");
-        };
-    }
-}

